import { readTextOr } from "../fsutil";
import { absPath, fileSize, isBinary, listProjectFiles } from "../scan";
import { detectMemoryFiles, isAgentFile } from "../logs/memoryFiles";
import { git, gitRoot } from "../git";
import { analyze, splitLines, type Heading } from "./markdown";
import { archivePath, isArchived, isPlaceholder, listArchived, readSource } from "./sources";

/**
 * Scan (pipeline step 1): find candidate source files. Skips dependency
 * folders, generated files, anything git ignores, and binaries. Names are
 * hints, not rules: classification decides by content.
 */

export interface Candidate {
  path: string;
  bytes: number;
  lines: number;
  headings: Heading[];
  /** Hints computed by code, shown to the classifier. */
  hints: {
    agentFile: boolean;
    memoryName: boolean;
    mentionedByAgentFile: boolean;
    versionHeadings: number;
    dateHeadings: number;
    sectionSignHeadings: number;
    mustNeverLines: number;
    topListItems: number;
    commits?: number;
  };
}

const TEXT_SOURCE_RE = /\.(md|mdx|markdown)$/i;
const MAX_BYTES = 5 * 1024 * 1024;
const GENERATED_RE = /(auto-?generated|do not edit|generated by)/i;
/** Files the tool writes for the agent (path rules, the updater helper, its command): never memory to build from. */
const TOOL_FILE_RE = /(^|\/)\.claude\/(rules|agents|commands)\/cube-[^/]*\.md$/;

export function scanCandidates(root: string, projectFiles: string[] = listProjectFiles(root)): Candidate[] {
  // Archived sources are read from the archive, even if their placeholder was deleted.
  const files = [...new Set([...projectFiles, ...listArchived(root)])].sort();
  const memory = new Set(detectMemoryFiles(root, files));
  const agentFiles = new Set(files.filter(isAgentFile));
  const hasGit = !!gitRoot(root);
  const out: Candidate[] = [];
  for (const f of files) {
    const isText = TEXT_SOURCE_RE.test(f) || agentFiles.has(f);
    if (!isText || TOOL_FILE_RE.test(f)) continue;
    const abs = isArchived(root, f) ? archivePath(root, f) : absPath(root, f);
    const bytes = fileSize(abs);
    if (bytes === 0 || bytes > MAX_BYTES || isBinary(abs)) continue;
    const text = readSource(root, f);
    // A placeholder whose original isn't in the archive holds nothing to build from (see orphanPlaceholders).
    if (!text.trim() && isPlaceholder(readTextOr(abs, ""))) continue;
    const head = text.slice(0, 400);
    if (GENERATED_RE.test(head) && !agentFiles.has(f)) continue;
    const info = analyze(text);
    const headings = info.flatMap((l) => (l.heading ? [l.heading] : []));
    const hints: Candidate["hints"] = {
      agentFile: agentFiles.has(f),
      memoryName: memory.has(f) && !agentFiles.has(f),
      mentionedByAgentFile: memory.has(f),
      versionHeadings: headings.filter((h) => /\bv?\d+\.\d+(\.\d+)?\b/.test(h.text)).length,
      dateHeadings: headings.filter((h) => /\b\d{4}-\d{2}-\d{2}\b/.test(h.text)).length,
      sectionSignHeadings: headings.filter((h) => /§\s*\d+/.test(h.text)).length,
      mustNeverLines: info.filter((l) => !l.inFence && /\b(never|must not|do not|don't|always|must)\b/i.test(l.text)).length,
      topListItems: info.filter((l) => l.topItem).length,
    };
    if (hasGit) {
      const r = git(["rev-list", "--count", "HEAD", "--", f], root);
      if (r.ok) hints.commits = Number(r.stdout.trim()) || 0;
    }
    out.push({ path: f, bytes, lines: splitLines(text).length, headings, hints });
  }
  return out;
}

/** A compact outline for prompts: every heading up to `max`, sampled evenly beyond that. */
export function outline(headings: Heading[], max = 60): string {
  const pick = headings.length <= max ? headings : sample(headings, max);
  const lines = pick.map((h) => `L${h.line} ${"#".repeat(h.level)} ${h.text.slice(0, 120)}`);
  if (pick.length < headings.length) lines.push(`(${headings.length - pick.length} more headings not shown)`);
  return lines.join("\n");
}

function sample<T>(xs: T[], n: number): T[] {
  if (xs.length <= n) return xs;
  const head = xs.slice(0, Math.ceil(n / 2));
  const rest = xs.slice(head.length);
  const step = rest.length / (n - head.length);
  const tail: T[] = [];
  for (let i = 0; i < n - head.length; i++) tail.push(rest[Math.floor(i * step)]);
  return [...head, ...tail];
}

export function firstLines(root: string, path: string, n: number, maxChars = 2500): string {
  const lines = splitLines(readSource(root, path)).slice(0, n);
  let out = lines.map((l, i) => `${i + 1}| ${l}`).join("\n");
  if (out.length > maxChars) out = `${out.slice(0, maxChars)}\n(…cut)`;
  return out;
}

/** Lines [start..start+n) of a file, numbered, for showing the AI what an entry looks like. */
export function linesAt(root: string, path: string, start: number, n: number, maxChars = 1200): string {
  const lines = splitLines(readSource(root, path));
  let out = lines
    .slice(start - 1, start - 1 + n)
    .map((l, i) => `${start + i}| ${l}`)
    .join("\n");
  if (out.length > maxChars) out = `${out.slice(0, maxChars)}\n(…cut)`;
  return out;
}
